hooks.command:
python3 -c 'import json,os,sys; data=json.load(sys.stdin); ti=data.get("tool_input",{}); path=ti.get("file_path") or ti.get("notebook_path") or ""; base=os.path.basename(path); is_real_env=base.startswith(".env") and not base.endswith(".example"); msg="";
if is_real_env: msg="Cảnh báo: đang sửa file .env thật. Chỉ tiếp tục nếu người dùng yêu cầu rõ ràng; ưu tiên cập nhật .env.example."
print(json.dumps({"hookSpecificOutput":{"hookEventName":"PreToolUse","additionalContext":msg}} if msg else {}))'

python3 -c 'import json,os,sys; data=json.load(sys.stdin); ti=data.get("tool_input",{}); path=ti.get("file_path") or ti.get("notebook_path") or ""; rel=os.path.relpath(path, os.getcwd()) if path.startswith(os.getcwd()) else path; notes=[];
if rel.startswith("frontend/") and rel.endswith((".ts",".tsx",".js",".jsx")): notes.append("Frontend file changed: before finishing, consider `cd frontend && pnpm lint` and for UI changes manually verify http://localhost:3000.")
if rel.startswith("service/lenshub/") and rel.endswith(".java"): notes.append("Lenshub Java file changed: before finishing, consider `cd service/lenshub && ./gradlew test` or a targeted `./gradlew test --tests ...`.")
if rel.endswith(("application.yml",".env.example")): notes.append("Config file changed: verify matching environment variables and avoid committing real secrets.")
print(json.dumps({"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"\n".join(notes)}} if notes else {}))'
